import axios from 'axios';

const instance = axios.create({
  baseURL: process.env.REACT_APP_SERVER_URL,
  withCredentials: true,
});

const getAccessToken = () => {
  const tokenRaw = localStorage.getItem("persist:auth");
  if (!tokenRaw) return null;

  try {
    const parsed = JSON.parse(tokenRaw);
    const user = parsed.user ? JSON.parse(parsed.user) : null;
    return user?.token || null;
  } catch {
    return null;
  }
};

instance.interceptors.request.use((config) => {
  const token = getAccessToken();
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

// Response interceptor để làm mới token nếu bị 401
instance.interceptors.response.use(
  res => res,
  async (error) => {
    const originalRequest = error.config;

    if (
      error.response?.status === 401 &&
      !originalRequest._retry &&
      !originalRequest.url.includes("/refreshtoken")
    ) {
      originalRequest._retry = true;
      try {
        const res = await axios.post(
          `${process.env.REACT_APP_SERVER_URL}/api/user/refreshtoken`,
          {},
          { withCredentials: true }
        );

        const newAccessToken = res.data.token;

        const persistAuth = window.localStorage.getItem("persist:auth");
        if (persistAuth) {
          const parsed = JSON.parse(persistAuth);
          const user = parsed.user ? JSON.parse(parsed.user) : null;

          const updated = {
            ...parsed,
            user: JSON.stringify({
              ...user,
              token: newAccessToken,
            }),
          };

          window.localStorage.setItem("persist:auth", JSON.stringify(updated));
        }
        originalRequest.headers.Authorization = `Bearer ${newAccessToken}`;
        return instance(originalRequest);
      } catch (err) {
        window.localStorage.clear();
        window.location.href = "/";
        return Promise.reject(err);
      }
    }

    return Promise.reject(error);
  }
);

export default instance;
